WITH store_agg AS ( SELECT ss_customer_sk AS customer_sk, SUM(ss_net_profit) AS store_net_profit, COUNT(*) AS store_txn_cnt FROM store_sales GROUP BY ss_customer_sk ), web_agg AS ( SELECT ws_bill_customer_sk AS customer_sk, SUM(ws_net_profit) AS web_net_profit, COUNT(*) AS web_txn_cnt FROM web_sales GROUP BY ws_bill_customer_sk ), cust_demo AS ( SELECT c.c_customer_sk, c.c_first_name, c.c_last_name, cd.cd_gender, cd.cd_marital_status, cd.cd_education_status FROM customer c LEFT JOIN customer_demographics cd ON c.c_current_cdemo_sk = cd.cd_demo_sk ) SELECT cd.c_customer_sk, cd.c_first_name, cd.c_last_name, cd.cd_gender, cd.cd_marital_status, COALESCE(sa.store_net_profit, 0) AS store_net_profit, COALESCE(wa.web_net_profit, 0) AS web_net_profit, COALESCE(sa.store_net_profit, 0) + COALESCE(wa.web_net_profit, 0) AS total_net_profit, CASE WHEN COALESCE(sa.store_net_profit, 0) + COALESCE(wa.web_net_profit, 0) > 20000 THEN 'Platinum' WHEN COALESCE(sa.store_net_profit, 0) + COALESCE(wa.web_net_profit, 0) > 10000 THEN 'Gold' ELSE 'Silver' END AS customer_tier, DENSE_RANK() OVER (ORDER BY COALESCE(sa.store_net_profit, 0) + COALESCE(wa.web_net_profit, 0) DESC) AS profit_rank, ROW_NUMBER() OVER (PARTITION BY cd.cd_gender ORDER BY COALESCE(sa.store_net_profit, 0) + COALESCE(wa.web_net_profit, 0) DESC) AS gender_rank FROM cust_demo cd LEFT JOIN store_agg sa ON sa.customer_sk = cd.c_customer_sk LEFT JOIN web_agg wa ON wa.customer_sk = cd.c_customer_sk WHERE COALESCE(sa.store_net_profit, 0) + COALESCE(wa.web_net_profit, 0) > 0 ORDER BY profit_rank LIMIT 50
